---RefreshBoardByContent 根据内容刷新提示板
---@param entryId integer @ 词条ID
function ActivityCrisisContractTips:RefreshBoardByEntryId(entryId)
    local entryVo = ActivityCrisisUtils.GetCrisisEventEntryVo(entryId)
    if not isNull(entryVo) then
        local env = CfUtils.GetLuaScr(self.ActivityCrisisContractLevelListNode,"Game.Activity.CrisisContract.Cell.ActivityCrisisContractLevelListNode")
        if not isNull(env) then
            env:RefreshCommonShow(entryVo)
        end
        CfUtils.FillText(self.ContentTxt,entryVo.description)

        local taskVo = ActivityCrisisUtils.GetCrisisEventTaskVo(entryVo.unlockTask)
        self.taskVo = taskVo
        if not isNull(taskVo) then
            local levelVo = ActivityCrisisUtils.GetCrisisEventLevelVo(taskVo.questId)
            self.levelVo = levelVo
            local levelName = ""
            if not isNull(levelVo) then
                levelName = levelVo.name
            end
            CfUtils.FillText(self.ContentTxt2,localize("在怪谈事件<color=#05f1e6>【_levelName_】</color>中完成怪谈档案：<color=#05f1e6>_desc_</color>",{_levelName_ = levelName,_desc_ = taskVo.desc}))
        end
    end
end

function ActivityCrisisContractTips:OnFontStyleButtonClick()
    if not isNull(self.taskVo) then
        local isRank = self.levelVo.type == ActivityCrisisUtils.LevelType.Normal
        local questData
        local dojo = ActivityCrisisUtils.GetActivityCrisisMgr():GetActivityDojo()
        if isRank then
            questData = dojo:GetNormalQuest()
        else
            questData = dojo:GetRotationQuest()
        end

        local isLock = false

        for i, v in ipairs(questData) do
            if v.questId == self.levelVo.id then
                if v.unlockCountdown > 0 and v.unlockCountdown - os.time() > 0 then
                    isLock = true
                    break
                end
            end
        end

        if isLock then
            GameUtils.Toast(localize("目标事件开放时间未到"))
            return
        end

        Events.Broadcast("DestoryCommonTipsBord", nil)
        Events.Broadcast(Constants.EventNames.CrisisLevelRefreshEvent,self.taskVo.questId,isRank)
    end
end

